import { z } from 'zod';
const cnicRegex = /^\d{5}-\d{7}-\d$/;
export const createCustomerSchema = z.object({
    name: z.string().min(2).max(100),
    cnic: z.string().regex(cnicRegex, 'CNIC format: XXXXX-XXXXXXX-X'),
    phone: z.string().min(10).max(15),
    fatherName: z.string().max(100).optional(),
    cnicExpiry: z.string().max(20).optional(),
    address: z.string().max(500).optional(),
    area: z.string().max(100).optional(),
    officeAddress: z.string().min(1, 'Office address is required').max(500),
    salary: z.preprocess((v) => (v === '' || v === null || v === undefined || (typeof v === 'number' && isNaN(v))) ? undefined : Number(v), z.number({ required_error: 'Salary is required', invalid_type_error: 'Enter a valid salary amount' }).positive('Salary must be greater than 0')),
    occupation: z.string().max(100).optional(),
    employer: z.string().max(100).optional(),
    guarantorName: z.string().max(100).optional(),
    guarantorPhone: z.string().max(15).optional(),
    guarantorCnic: z.string().regex(cnicRegex, 'CNIC format: XXXXX-XXXXXXX-X').optional().or(z.literal('')),
    guarantorAddress: z.string().max(500).optional(),
    guarantorRelation: z.string().max(50).optional(),
    guarantor2Name: z.string().max(100).optional(),
    guarantor2Phone: z.string().max(15).optional(),
    guarantor2Cnic: z.string().regex(cnicRegex, 'CNIC format: XXXXX-XXXXXXX-X').optional().or(z.literal('')),
    guarantor2Address: z.string().max(500).optional(),
    guarantor2Relation: z.string().max(50).optional(),
    photoUrl: z.string().url('Customer photo is required'),
    cnicFrontUrl: z.string().url('CNIC front image is required'),
    cnicBackUrl: z.string().url('CNIC back image is required'),
    blankChequeUrl: z.string().url().optional(),
    customerType: z.enum(['regular', 'dukaan-dar']).optional(),
    shopName: z.string().max(100).optional(),
    shopAddress: z.string().max(500).optional(),
    businessType: z.string().max(100).optional(),
    guarantorShopName: z.string().max(100).optional(),
    guarantorShopAddress: z.string().max(500).optional(),
    guarantor2ShopName: z.string().max(100).optional(),
    guarantor2ShopAddress: z.string().max(500).optional(),
    guarantorCnicFrontUrl: z.string().url().optional(),
    guarantorCnicBackUrl: z.string().url().optional(),
    guarantor2CnicFrontUrl: z.string().url().optional(),
    guarantor2CnicBackUrl: z.string().url().optional(),
    cnicFrontHash: z.string().max(64).optional(),
    cnicBackHash: z.string().max(64).optional(),
    blankChequeHash: z.string().max(64).optional(),
    chequeBank: z.string().max(100).optional(),
    chequeAccountNo: z.string().max(30).optional(),
    chequeNo: z.string().max(20).optional(),
    dob: z.string().max(10).optional(),
    referredById: z.string().optional(),
});
export const updateCustomerSchema = createCustomerSchema.partial().extend({
    cnic: z.string().regex(cnicRegex, 'Format: XXXXX-XXXXXXX-X').optional().or(z.literal('')),
    tags: z.array(z.string().max(50)).max(20).optional(),
});
